}

function singlePaneLayout(): LayoutState {
  const sourceTab: TerminalTab = { id: "tab-source", label: "source", sessionId: "session-source" };
  const targetTab: TerminalTab = { id: "tab-target", label: "target", sessionId: "session-target" };
  return {
    tabs: [sourceTab, targetTab],
    activeTabId: sourceTab.id,
    tabGroups: {
      "group-main": {
        id: "group-main",
        tabIds: [sourceTab.id, targetTab.id],
        activeTabId: sourceTab.id,
      },
    },
    tabGroupLayout: { type: "group", groupId: "group-main" },
    focusedGroupId: "group-main",
    layoutsByTabId: {
      [sourceTab.id]: {
        root: { type: "leaf", leafId: "leaf-source" },
        activeLeafId: "leaf-source",
        expandedLeafId: null,
        sessionIdsByLeafId: { "leaf-source": "session-source" },
      },
      [targetTab.id]: {
        root: { type: "leaf", leafId: "leaf-target" },
        activeLeafId: "leaf-target",
        expandedLeafId: null,
        sessionIdsByLeafId: { "leaf-target": "session-target" },
      },
    },
  };
}

describe("TerminalSplitView pane-handle edge execution", () => {
  it("registers every pane toolbar as a draggable with pane/session source payload", () => {
    render(
      <TerminalSplitView
        layout={splitLayout()}
        sessions={{
          "session-a": session("session-a"),
          "session-b": session("session-b"),
          "session-c": session("session-c"),
        }}
      />,
    );

    expect(dndHarness.draggableArgs).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          id: "pane:tab-main:leaf-a",
          data: {
            type: "pane",
            tabId: "tab-main",
            sourcePaneId: "leaf-a",
            sourceSessionId: "session-a",
          },
        }),
      ]),
    );
    expect(dndHarness.draggableArgs.some((args) => args.disabled === true)).toBe(false);
  });

  it("composes detach + pane-targeted tab merge so the dragged PTY is moved instead of respawned", () => {
    const onDetachPaneToTab = vi.fn(() => "tab-detached");
    const onMoveTabToSplit = vi.fn();

    render(
      <TerminalSplitView
        layout={splitLayout()}
        sessions={{
          "session-a": session("session-a"),
          "session-b": session("session-b"),
          "session-c": session("session-c"),
        }}
        onDetachPaneToTab={onDetachPaneToTab}
        onMoveTabToSplit={onMoveTabToSplit}
      />,
    );

    expect(dndHarness.props?.onDragStart).toBeTypeOf("function");
    expect(dndHarness.props?.onDragEnd).toBeTypeOf("function");

    dndHarness.props!.onDragStart!({
      active: {
        data: {
          current: {
            type: "pane",
            tabId: "tab-main",
            sourcePaneId: "leaf-a",
            sourceSessionId: "session-a",
          },
        },
      },
    });
    dndHarness.props!.onDragEnd!({
      over: { data: { current: { type: "pane-edge", tabId: "tab-main", leafId: "leaf-c", edge: "top" } } },
    });

    expect(onDetachPaneToTab).toHaveBeenCalledWith("tab-main", "leaf-a", "group-main");
    expect(onMoveTabToSplit).toHaveBeenCalledWith(
      "tab-detached",
      "group-main",
      "vertical",
      "first",
      { tabId: "tab-main", leafId: "leaf-c" },
    );
  });

  it("moves a one-pane source tab directly into the hovered pane edge instead of disabling the handle", () => {
    const onDetachPaneToTab = vi.fn(() => "unexpected-detached-tab");
    const onMoveTabToSplit = vi.fn();

    render(
      <TerminalSplitView
        layout={singlePaneLayout()}
        sessions={{
          "session-source": session("session-source"),
          "session-target": session("session-target"),
        }}
        onDetachPaneToTab={onDetachPaneToTab}
        onMoveTabToSplit={onMoveTabToSplit}
      />,
    );

    expect(dndHarness.draggableArgs).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          id: "pane:tab-source:leaf-source",
          data: {
            type: "pane",
            tabId: "tab-source",
            sourcePaneId: "leaf-source",
            sourceSessionId: "session-source",
          },
        }),
      ]),
    );

    dndHarness.props!.onDragStart!({
      active: {
        data: {
          current: {
            type: "pane",
            tabId: "tab-source",
            sourcePaneId: "leaf-source",
            sourceSessionId: "session-source",
          },
        },
      },
    });
    dndHarness.props!.onDragEnd!({
      over: { data: { current: { type: "pane-edge", tabId: "tab-target", leafId: "leaf-target", edge: "right" } } },
    });

    expect(onDetachPaneToTab).not.toHaveBeenCalled();
    expect(onMoveTabToSplit).toHaveBeenCalledWith(
      "tab-source",
      "group-main",
      "horizontal",
      "second",
      { tabId: "tab-target", leafId: "leaf-target" },
    );
  });
});

import { describe, expect, it } from "vitest";

import type { LayoutState, TerminalTab } from "../lib/types";
import { getGroupForTab, layoutReducer, normalizeLayout } from "./layout";
import { moveTabIntoPaneSplit } from "./tabPaneDrop";

function sameTabLayout(): LayoutState {
  const tab: TerminalTab = { id: "tab-main", label: "main", sessionId: "session-a" };
  return normalizeLayout({
    tabs: [tab],
    activeTabId: tab.id,
    layoutsByTabId: {
      [tab.id]: {
        root: {
          type: "split",
          direction: "horizontal",
          first: { type: "leaf", leafId: "leaf-a" },
          second: {
            type: "split",
            direction: "vertical",
            first: { type: "leaf", leafId: "leaf-b" },
            second: { type: "leaf", leafId: "leaf-c" },
            ratio: 0.5,
          },
          ratio: 0.4,
        },
        activeLeafId: "leaf-a",
        expandedLeafId: null,
        sessionIdsByLeafId: {
          "leaf-a": "session-a",
          "leaf-b": "session-b",
          "leaf-c": "session-c",
        },
      },
    },
  });
}

describe("pane-handle edge drop composition", () => {
  it("detaches the existing pane session and reinserts that exact leaf at the target edge", () => {
    const state = sameTabLayout();
    const groupId = getGroupForTab(state, "tab-main")!.id;
    const detachedTab: TerminalTab = { id: "tab-detached", label: "main", sessionId: "session-a" };

    const detached = layoutReducer(state, {
      type: "DETACH_PANE_TO_TAB",
      sourceTabId: "tab-main",
      leafId: "leaf-a",
      newTab: detachedTab,
      targetGroupId: groupId,
    });
    const next = moveTabIntoPaneSplit(
      detached,
      detachedTab.id,
      "tab-main",
      "leaf-c",
      "vertical",
      "first",
    );

    expect(next.tabs.map((tab) => tab.id)).toEqual(["tab-main"]);
    expect(next.layoutsByTabId["tab-main"].root).toEqual({
      type: "split",
      direction: "vertical",
      first: { type: "leaf", leafId: "leaf-b" },
      second: {
        type: "split",
        direction: "vertical",
        first: { type: "leaf", leafId: "leaf-a" },
        second: { type: "leaf", leafId: "leaf-c" },
        ratio: 0.5,
      },
      ratio: 0.5,
    });
    expect(next.layoutsByTabId["tab-main"].activeLeafId).toBe("leaf-a");
    expect(next.layoutsByTabId["tab-main"].sessionIdsByLeafId).toEqual({
      "leaf-a": "session-a",
      "leaf-b": "session-b",
      "leaf-c": "session-c",
    });
  });

  it("preserves pane ownership when a handle is moved to an edge in another tab", () => {
    const source: TerminalTab = { id: "tab-source", label: "source", sessionId: "session-moved" };
    const target: TerminalTab = { id: "tab-target", label: "target", sessionId: "session-target" };
    const state = normalizeLayout({
      tabs: [source, target],
      activeTabId: source.id,
      layoutsByTabId: {
        [source.id]: {
          root: {
            type: "split",
            direction: "horizontal",
            first: { type: "leaf", leafId: "leaf-moved" },
            second: { type: "leaf", leafId: "leaf-remain" },
            ratio: 0.5,
          },
          activeLeafId: "leaf-moved",
          expandedLeafId: null,
          sessionIdsByLeafId: {
            "leaf-moved": "session-moved",
            "leaf-remain": "session-remain",
          },
        },
        [target.id]: {
          root: { type: "leaf", leafId: "leaf-target" },
          activeLeafId: "leaf-target",
          expandedLeafId: null,
          sessionIdsByLeafId: { "leaf-target": "session-target" },
        },
      },
    });
    const targetGroupId = getGroupForTab(state, target.id)!.id;
    const detachedTab: TerminalTab = { id: "tab-detached", label: "source", sessionId: "session-moved" };

    const detached = layoutReducer(state, {
      type: "DETACH_PANE_TO_TAB",
      sourceTabId: source.id,
      leafId: "leaf-moved",
      newTab: detachedTab,
      targetGroupId,
    });
    const next = moveTabIntoPaneSplit(
      detached,
      detachedTab.id,
      target.id,
      "leaf-target",
      "horizontal",
      "second",
    );

    expect(next.tabs.find((tab) => tab.id === source.id)).toMatchObject({ sessionId: "session-remain" });
    expect(next.layoutsByTabId[source.id]).toMatchObject({
      root: { type: "leaf", leafId: "leaf-remain" },
      activeLeafId: "leaf-remain",
      sessionIdsByLeafId: { "leaf-remain": "session-remain" },
    });
    expect(next.layoutsByTabId[target.id].root).toEqual({
      type: "split",
      direction: "horizontal",
      first: { type: "leaf", leafId: "leaf-target" },
      second: { type: "leaf", leafId: "leaf-moved" },
      ratio: 0.5,
    });
