  it("keeps pane swaps inside their source tab and ignores pane-to-group-edge split", () => {
    expect(
      resolveWorkspaceDropCommand(paneDrag, {
        type: "pane-leaf",
        tabId: "tab-source",
        leafId: "leaf-other",
      }),
