 122	        return {
 123	          type: "move-tab-to-group",
 124	          tabId: active.tabId,
 125	          targetGroupId: over.groupId,
 126	          targetIndex: over.index,
 127	        };
 128	      case "group-body":
 129	        return {
 130	          type: "move-tab-to-group",
 131	          tabId: active.tabId,
